class Editor:
    def __init__(self):
        self.text, self.undos, self.redos = "", [], []

    def _apply(self, action):
        kind, s = action
        if kind == "type":
            self.text += s
        else:
            self.text = self.text[:len(self.text) - len(s)]

    def _reverse(self, action):
        kind, s = action
        return ("delete" if kind == "type" else "type", s)

    def type(self, s):
        self._apply(("type", s))
        self.undos.append(("type", s))
        self.redos.clear()

    def delete(self, n):
        gone = self.text[len(self.text) - n:] if n else ""
        self._apply(("delete", gone))
        self.undos.append(("delete", gone))
        self.redos.clear()

    def undo(self):
        if self.undos:
            a = self.undos.pop()
            self._apply(self._reverse(a))
            self.redos.append(a)

    def redo(self):
        if self.redos:
            a = self.redos.pop()
            self._apply(a)
            self.undos.append(a)

