def nearest(streets, depots):
    g = defaultdict(list)
    for a, b, m in streets:
        g[a].append((b, m))
        g[b].append((a, m))
    best = {}
    heap = [(0, d, d) for d in depots]
    heapq.heapify(heap)
    while heap:
        t, src, v = heapq.heappop(heap)
        if v in best:
            continue
        best[v] = (t, src)
        for w, m in g[v]:
            if w not in best:
                heapq.heappush(heap, (t + m, src, w))
    return best

def route(streets, src, dst, closed):
    g = defaultdict(list)
    for a, b, m in streets:
        if frozenset((a, b)) not in closed:
            g[a].append((b, m))
            g[b].append((a, m))
    dist, parent = {src: 0}, {}
    heap = [(0, src)]
    while heap:
        d, v = heapq.heappop(heap)
        if d > dist[v]:
            continue
        for w, m in g[v]:
            if d + m < dist.get(w, float("inf")):
                dist[w] = d + m
                parent[w] = v
                heapq.heappush(heap, (d + m, w))
    if dst not in dist:
        return []
    path = [dst]
    while path[-1] != src:
        path.append(parent[path[-1]])
    return path[::-1]

def dijkstra(n, edges, s):
    g = [[] for _ in range(n)]
    for u, v, w in edges:
        g[u].append((v, w))
    dist = [float("inf")] * n
    dist[s] = 0
    heap = [(0, s)]
    while heap:
        d, v = heapq.heappop(heap)
        if d > dist[v]:
            continue
        for w, t in g[v]:
            if d + t < dist[w]:
                dist[w] = d + t
                heapq.heappush(heap, (d + t, w))
    return dist

