def count_smaller(nums):
    vals = sorted(set(nums))
    rank = {v: i for i, v in enumerate(vals)}
    m = len(vals)
    t = [0] * (2 * m)
    out = []
    for x in reversed(nums):
        lo, hi, c = m, m + rank[x], 0
        while lo < hi:
            if lo & 1:
                c += t[lo]
                lo += 1
            if hi & 1:
                hi -= 1
                c += t[hi]
            lo //= 2
            hi //= 2
        out.append(c)
        i = rank[x] + m
        while i:
            t[i] += 1
            i //= 2
    return out[::-1]

