def kth_present(n, ops):
    size = 1
    while size < n:
        size *= 2
    t = [0] * (2 * size)
    out = []
    for op, x in ops:
        if op == "add" or op == "remove":
            i = x + size
            want = 1 if op == "add" else 0
            if t[i] != want:
                d = 1 if want else -1
                while i:
                    t[i] += d
                    i //= 2
        else:
            if t[1] < x:
                out.append(-1)
                continue
            i, k = 1, x
            while i < size:
                if t[2 * i] >= k:
                    i = 2 * i
                else:
                    k -= t[2 * i]
                    i = 2 * i + 1
            out.append(i - size)
    return out

