def flip_and_count(bits, ops):
    n = len(bits)
    cnt, fl = [0] * (4 * n), [False] * (4 * n)
    def build(x, lo, hi):
        if lo == hi:
            cnt[x] = bits[lo]
            return
        m = (lo + hi) // 2
        build(2 * x, lo, m)
        build(2 * x + 1, m + 1, hi)
        cnt[x] = cnt[2 * x] + cnt[2 * x + 1]
    def apply(x, lo, hi):
        cnt[x] = (hi - lo + 1) - cnt[x]
        fl[x] = not fl[x]
    def push(x, lo, hi):
        if fl[x]:
            m = (lo + hi) // 2
            apply(2 * x, lo, m)
            apply(2 * x + 1, m + 1, hi)
            fl[x] = False
    def flip(x, lo, hi, l, r):
        if r < lo or hi < l:
            return
        if l <= lo and hi <= r:
            apply(x, lo, hi)
            return
        push(x, lo, hi)
        m = (lo + hi) // 2
        flip(2 * x, lo, m, l, r)
        flip(2 * x + 1, m + 1, hi, l, r)
        cnt[x] = cnt[2 * x] + cnt[2 * x + 1]
    def count(x, lo, hi, l, r):
        if r < lo or hi < l:
            return 0
        if l <= lo and hi <= r:
            return cnt[x]
        push(x, lo, hi)
        m = (lo + hi) // 2
        return count(2 * x, lo, m, l, r) + count(2 * x + 1, m + 1, hi, l, r)
