def min_cut(n, edges, s, t):
    adj, to, cap = [[] for _ in range(n)], [], []
    for a, b, c in edges:
        adj[a].append(len(to)); to.append(b); cap.append(c)
        adj[b].append(len(to)); to.append(a); cap.append(0)
    while True:
        prev = [-1] * n
        prev[s] = -2
        q = deque([s])
        while q and prev[t] == -1:
            v = q.popleft()
            for e in adj[v]:
                w = to[e]
                if cap[e] > 0 and prev[w] == -1:
                    prev[w] = e
                    q.append(w)
        if prev[t] == -1:
            break
        push, v = float("inf"), t
        while v != s:
            e = prev[v]
            push = min(push, cap[e])
            v = to[e ^ 1]
        v = t
        while v != s:
            e = prev[v]
            cap[e] -= push
            cap[e ^ 1] += push
            v = to[e ^ 1]
    seen = [False] * n
    seen[s] = True
    st = [s]
    while st:
        v = st.pop()
        for e in adj[v]:
