def dominoes(grid):
    R, C = len(grid), len(grid[0])
    idx = {}
    for r in range(R):
        for c in range(C):
            if grid[r][c] == ".":
                idx[(r, c)] = len(idx)
    n = len(idx)
    adj = [[] for _ in range(n)]
    for (r, c), i in idx.items():
        if (r + c) % 2 == 0:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                if (r + dr, c + dc) in idx:
                    adj[i].append(idx[(r + dr, c + dc)])
    owner = [-1] * n
    def try_kuhn(v, seen):
        for j in adj[v]:
            if not seen[j]:
                seen[j] = True
                if owner[j] == -1 or try_kuhn(owner[j], seen):
                    owner[j] = v
                    return True
        return False
    return sum(1 for (r, c), i in idx.items() if (r + c) % 2 == 0 and try_kuhn(i, [False] * n))

